PRAGMA recursive_triggers=OFF; CREATE TEMP TABLE tbl(a PRIMARY KEY,b) WITHOUT ROWID; CREATE INDEX tbl_idx ON tbl(b); INSERT INTO tbl VALUES(1,2),(3,4); CREATE TRIGGER bu BEFORE UPDATE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER au AFTER UPDATE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER bd BEFORE DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TRIGGER ad AFTER DELETE ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),old.a,old.b,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),0,0); END; CREATE TRIGGER bi BEFORE INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; CREATE TRIGGER ai AFTER INSERT ON tbl BEGIN INSERT INTO rlog VALUES((SELECT coalesce(max(idx),0)+1 FROM rlog),0,0,(SELECT coalesce(sum(a),0) FROM tbl),(SELECT coalesce(sum(b),0) FROM tbl),new.a,new.b); END; UPDATE tbl SET a=a*10,b=b*10; DELETE FROM rlog; DELETE FROM tbl; DELETE FROM rlog; INSERT INTO tbl VALUES(5,6);